            _allTasks.Add(task);
            if (task.Status != created.Status)
            {
                await TaskService.UpdateTaskStatusAsync(task.Id, status);
            }
            _addingColumn = null;
        }
        catch (Exception ex)
        {
            _formError = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
