+            <span class="visually-hidden">Loading…</span>
+        </div>
+    </div>
+}
+else if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
+    </div>
+}
+else
+{
+    @* ── Stats bar ── *@
+    <div class="row g-2 mb-3">
+        <div class="col"><div class="card text-center p-2"><strong>Total</strong><span>@_allTasks.Count</span></div></div>
+        @foreach (var col in Columns)
+        {
+            <div class="col">
+                <div class="card text-center p-2">
+                    <strong>@col</strong><span>@CountByStatus(col)</span>
+                </div>
+            </div>
+        }
+        <div class="col"><div class="card text-center p-2 text-danger"><strong>Overdue</strong><span>@_allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span></div></div>
+    </div>
+
+    @* ── Search bar ── *@
+    <div class="mb-3">
+        <input type="text" class="form-control" placeholder="Search tasks by title…"
+               @bind="_searchText" @bind:event="oninput" />
+    </div>
+
+    @* ── Columns ── *@
+    <div class="row g-3">
+        @for (var i = 0; i < Columns.Length; i++)
+        {
+            var colIndex = i;
+            var colName = Columns[colIndex];
+            var tasks = FilteredTasksForStatus(colName);
+
+            <div class="col-md-4">
+                <div class="card h-100">
+                    <div class="card-header d-flex justify-content-between align-items-center">
+                        <strong>@colName</strong>
+                        <span class="badge bg-secondary">@tasks.Count</span>
+                    </div>
+
+                    <div class="card-body d-flex flex-column gap-2">
+                        @foreach (var task in tasks)
+                        {
+                            <div class="card shadow-sm">
+                                <div class="card-body p-2">
+                                    <h6 class="card-title mb-1">@task.Title</h6>
+                                    <p class="mb-1 text-muted small">@task.Assignee</p>
+                                    <div class="d-flex justify-content-between align-items-center mb-1">
+                                        <span class="badge @PriorityBadgeClass(task.Priority)">@task.Priority</span>
+                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
+                                    </div>
+                                    <div class="d-flex gap-1">
+                                        @if (colIndex > 0)
+                                        {
+                                            var leftStatus = Columns[colIndex - 1];
+                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_updating"
+                                                    @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
+                                                ← Move Left
+                                            </button>
+                                        }
+                                        @if (colIndex < Columns.Length - 1)
+                                        {
+                                            var rightStatus = Columns[colIndex + 1];
+                                            <button class="btn btn-sm btn-outline-secondary" disabled="@_updating"
+                                                    @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
+                                                Move Right →
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
+
+                        @* ── Inline add-task form ── *@
+                        @if (_addingColumn == colName)
+                        {
+                            <div class="card border-primary mt-auto">
+                                <div class="card-body p-2 d-flex flex-column gap-2">
+                                    <input type="text" class="form-control form-control-sm" placeholder="Title"
+                                           @bind="_newTitle" />
+                                    <input type="text" class="form-control form-control-sm" placeholder="Assignee"
+                                           @bind="_newAssignee" />
+                                    <select class="form-select form-select-sm" @bind="_newPriority">
+                                        <option value="">-- Priority --</option>
+                                        <option value="High">High</option>
+                                        <option value="Medium">Medium</option>
+                                        <option value="Low">Low</option>
+                                    </select>
+                                    <input type="date" class="form-control form-control-sm" @bind="_newDueDate" />
+                                    <div class="d-flex gap-1">
+                                        <button class="btn btn-sm btn-primary" disabled="@_saving"
+                                                @onclick="() => SaveTaskAsync(colName)">Save</button>
+                                        <button class="btn btn-sm btn-outline-secondary" @onclick="CancelAdd">Cancel</button>
+                                    </div>
+                                    @if (_formError is not null)
+                                    {
+                                        <div class="text-danger small">@_formError</div>
+                                    }
+                                </div>
+                            </div>
+                        }
+                        else
+                        {
+                            <button class="btn btn-sm btn-outline-primary mt-auto"
+                                    @onclick="() => ShowAddForm(colName)">
+                                + Add Task
+                            </button>
+                        }
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private static readonly string[] Columns = ["To Do", "In Progress", "Done"];
+
+    private List<TaskItem> _allTasks = new();
+    private bool _loading = true;
+    private bool _updating;
+    private bool _saving;
+    private string? _error;
+    private string _searchText = string.Empty;
+
+    // Add-task form state
+    private string? _addingColumn;
+    private string _newTitle = string.Empty;
+    private string _newAssignee = string.Empty;
+    private string _newPriority = string.Empty;
+    private DateTime _newDueDate = DateTime.Today;
+    private string? _formError;
+
+    protected override async Task OnInitializedAsync() => await LoadTasksAsync();
+
+    private async Task LoadTasksAsync()
+    {
+        _loading = true;
+        _error = null;
+        try
+        {
+            _allTasks = await TaskService.GetAllTasksAsync();
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private int CountByStatus(string status) =>
+        _allTasks.Count(t => t.Status == status);
+
+    private List<TaskItem> FilteredTasksForStatus(string status) =>
+        _allTasks
+            .Where(t => t.Status == status &&
+                        (string.IsNullOrWhiteSpace(_searchText) ||
+                         t.Title.Contains(_searchText, StringComparison.OrdinalIgnoreCase)))
+            .ToList();
+
+    private static string PriorityBadgeClass(string priority) => priority switch
+    {
+        "High" => "bg-danger",
+        "Medium" => "bg-warning text-dark",
+        "Low" => "bg-success",
+        _ => "bg-secondary"
+    };
+
+    private async Task MoveTaskAsync(int taskId, string newStatus)
+    {
+        _updating = true;
+        try
+        {
+            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
+            var idx = _allTasks.FindIndex(t => t.Id == taskId);
+            if (idx >= 0)
+            {
+                var old = _allTasks[idx];
+                _allTasks[idx] = old with { Status = newStatus };
+            }
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _updating = false;
+        }
+    }
+
+    private void ShowAddForm(string column)
+    {
+        _addingColumn = column;
+        _newTitle = string.Empty;
+        _newAssignee = string.Empty;
+        _newPriority = string.Empty;
+        _newDueDate = DateTime.Today;
+        _formError = null;
+    }
+
+    private void CancelAdd() => _addingColumn = null;
+
+    private async Task SaveTaskAsync(string status)
+    {
+        if (string.IsNullOrWhiteSpace(_newTitle) || string.IsNullOrWhiteSpace(_newAssignee) ||
+            string.IsNullOrWhiteSpace(_newPriority))
+        {
+            _formError = "Title, assignee, and priority are required.";
+            return;
+        }
+
+        _saving = true;
+        _formError = null;
+        try
+        {
+            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(),
+                _newPriority, _newDueDate);
+            // If the service doesn't set the status to the target column, adjust locally
+            var task = created.Status == status ? created : created with { Status = status };
+            _allTasks.Add(task);
+            if (task.Status != created.Status)
+            {
+                await TaskService.UpdateTaskStatusAsync(task.Id, status);
+            }
+            _addingColumn = null;
+        }
+        catch (Exception ex)
+        {
+            _formError = ex.Message;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+}
+

